INSERT INTO `courselessons` VALUES (1,1,'Bàn cờ và các khu vực','Sông, cung tướng và đường đi trên bàn cờ.','Bàn cờ Tướng có 9 đường dọc và 10 đường ngang, ở giữa là con sông. Mỗi bên có một cung 3x3 để Tướng và Sĩ hoạt động.','board',NULL,1),(2,1,'Nhận biết 7 loại quân','Tên gọi, mặt chữ và giá trị tương đối của các quân.','Bảy loại quân gồm Tướng, Sĩ, Tượng, Xe, Pháo, Mã và Tốt (quân Đỏ mang chữ Binh 兵, quân Đen mang chữ Tốt 卒). Quân Đỏ và quân Đen có mặt chữ khác nhau nhưng cách đi tương ứng.','theory',NULL,2),(3,2,'Xe: đi ngang và dọc','Nhận biết Xe và thực hành đường đi của Xe.','Xe đi ngang hoặc dọc không giới hạn, nhưng không được đi xuyên qua quân khác. Xe Đỏ bắt đầu ở hàng cuối, cột 0; Xe Đen bắt đầu ở hàng đầu, cột 0. Bạn điều khiển Xe Đỏ, còn Xe Đen là quân đối diện để quan sát và thực hành ăn quân.','board',NULL,1),(4,2,'Pháo: đi và ăn qua ngòi','Phân biệt nước đi thường và nước ăn của Pháo.','Pháo đi như Xe khi không ăn. Khi ăn, Pháo phải nhảy qua đúng một quân làm ngòi.','board',NULL,2),(5,2,'Mã: chữ L và cản chân','Thực hành tám hướng đi của Mã.','Mã đi theo hình chữ L. Nếu chân Mã bị chặn, hướng đó không đi được. Mã Đỏ bắt đầu ở hàng cuối, cột 1 và 7.','board',NULL,3),(6,3,'Chiếu tướng và chiếu hết','Nhận biết tình huống bị chiếu và kết thúc ván.','Chiếu là khi Tướng đang bị đe dọa bắt ở nước kế tiếp. Chiếu hết là khi bên bị chiếu không còn nước hợp lệ để thoát chiếu.','theory',NULL,1),(7,3,'Hòa cờ và ghi biên bản','Bắt bí, các trường hợp hòa và ký hiệu nước đi.','Bắt bí là không còn nước hợp lệ nhưng Tướng không bị chiếu. Khi ghi biên bản, hãy ghi số nước, quân đi, hướng đi và ô đến theo quy ước của ván.','theory',NULL,2),(8,4,'Nguyên tắc khai cuộc','Kiểm soát trung tâm và phát triển quân.','Ưu tiên đưa các quân hoạt động tốt, mở đường cho Xe, không di chuyển một quân quá nhiều lần và luôn chú ý an toàn của Tướng.','theory',NULL,1),(9,4,'Phối hợp và đổi quân','Xây dựng kế hoạch trung cuộc vững chắc.','Xe, Pháo, Mã nên hỗ trợ lẫn nhau. Chỉ đổi quân khi có lợi về vị trí, vật chất hoặc làm giảm áp lực lên Tướng của bạn.','theory',NULL,2),(10,2,'Tướng: một bước trong cung','Học giới hạn cung và cách đi của Tướng.','Tướng đi ngang hoặc dọc một ô trong cung 3x3. Tướng Đỏ bắt đầu ở hàng 9, cột 4.','board',NULL,4),(11,2,'Sĩ: đi chéo trong cung','Học bốn đường chéo hợp lệ của Sĩ.','Sĩ đi chéo một ô và chỉ hoạt động trong cung. Sĩ Đỏ bắt đầu ở hàng 9, cột 3 và 5.','board',NULL,5),(12,2,'Tượng: chéo hai ô','Học mắt Tượng và giới hạn qua sông.','Tượng đi chéo hai ô, không được qua sông và không được đi khi mắt Tượng bị chặn.','board',NULL,6),(13,2,'Tốt: qua sông đổi cách đi','Thực hành Tốt trước và sau khi qua sông.','Tốt đi thẳng một ô trước khi qua sông. Sau khi qua sông, Tốt được đi ngang nhưng không đi lùi.','board',NULL,7),(14,2,'Kết hợp Xe và Pháo','Ghép hai quân chủ lực trên thế khai cuộc.','Luyện phối hợp Xe và Pháo từ đúng vị trí khai cuộc của quân Đỏ.','board',NULL,8),(15,2,'Kết hợp Xe, Pháo và Mã','Bài thực hành phối hợp ba quân.','Sau khi nắm từng quân, hãy phối hợp Xe, Pháo và Mã để mở đường và ăn quân.','board',NULL,9),(16,2,'Tổng hợp 1: Nhận diện và luật đi','Ôn tập đầy đủ 7 loại quân trên bàn cờ khai cuộc.','Bài tổng hợp 1 dùng bàn cờ đầy đủ 32 quân để kiểm tra ký hiệu, vị trí ban đầu và hướng di chuyển cơ bản của từng loại quân.','board',NULL,10),(17,2,'Tổng hợp 2: Cản đường và ăn quân','Ôn tập đầy đủ vật cản, ngòi Pháo, chân Mã và luật ăn quân.','Bài tổng hợp 2 dùng bàn cờ đầy đủ 32 quân để kiểm tra vật cản, cách ăn quân và các giới hạn đặc biệt của từng quân.','board',NULL,11),(18,2,'Tổng hợp 3: Phối hợp thực chiến','Ôn tập toàn bộ quân cờ và cách phối hợp trong thế khai cuộc.','Bài tổng hợp 3 dùng bàn cờ đầy đủ 32 quân để kiểm tra phối hợp lực lượng, an toàn Tướng và các quy tắc thực chiến.','board',NULL,12),(19,2,'Tổng kết Module 2: Bàn cờ toàn diện','Thực hành đầy đủ 32 quân và kiểm tra toàn bộ luật di chuyển.','Bài tổng kết mở sau khi hoàn thành ba bài tổng hợp. Bàn cờ hiển thị đầy đủ 32 quân ở vị trí khai cuộc; bạn có thể chọn quân Đỏ để xem và thực hành các nước đi hợp lệ của Xe, Pháo, Mã, Tượng, Sĩ, Tướng và Tốt.','board',NULL,13);
/*!40000 ALTER TABLE `courselessons` ENABLE KEYS */;
UNLOCK TABLES;

