INSERT INTO `coursemodules` VALUES (1,'Vỡ lòng & Làm quen','Làm quen với bàn cờ, cung, sông và các quân cờ.','fa-seedling',1),(2,'Nhận biết quân & Nước đi','Học từng quân riêng lẻ, sau đó luyện phối hợp 2–3 quân trên thế khai cuộc chuẩn.','fa-arrows-up-down-left-right',2),(3,'Luật chơi & Nguyên tắc cơ bản','Hiểu chiếu tướng, chiếu hết, hòa cờ và cách ghi biên bản.','fa-scale-balanced',3),(4,'Chiến thuật cơ bản & Trung cuộc','Phát triển quân, phối hợp lực lượng và đổi quân có lợi.','fa-chess-knight',4);
