INSERT INTO `coursequizquestions` VALUES (1,1,'Khu vực nào nằm giữa hai bên bàn cờ?','[\"Cung tướng\",\"Con sông\",\"Đường biên\"]',1,'Con sông nằm giữa hai bên và chia bàn cờ thành hai nửa.',1),(2,2,'Quân nào có thể đi ngang hoặc dọc không giới hạn?','[\"Mã\",\"Xe\",\"Tượng\"]',1,'Xe đi thẳng ngang hoặc dọc trên các đường trống.',1),(3,3,'Xe đi như thế nào?','[\"Chéo\",\"Ngang hoặc dọc\",\"Theo hình chữ L\"]',1,'Xe đi ngang hoặc dọc trên các đường trống.',1),(4,4,'Pháo cần gì khi ăn quân?','[\"Hai ngòi\",\"Đúng một ngòi\",\"Không cần ngòi\"]',1,'Pháo phải nhảy qua đúng một quân làm ngòi để ăn.',1),(5,8,'Đâu là nguyên tắc khai cuộc tốt?','[\"Phát triển quân và kiểm soát trung tâm\",\"Di chuyển một quân liên tục\",\"Bỏ qua an toàn của Tướng\"]',0,'Phát triển quân và kiểm soát trung tâm giúp các quân phối hợp tốt hơn.',1),(6,5,'Mã bị cản bởi gì?','[\"Chân Mã\",\"Mắt Tượng\",\"Cung tướng\"]',0,'Mã không đi được nếu chân Mã bị chặn.',1),(7,6,'Chiếu hết nghĩa là gì?','[\"Tướng bị đe dọa nhưng còn đường thoát\",\"Tướng không bị đe dọa\",\"Bị chiếu và không còn nước hợp lệ để thoát\"]',2,'Chiếu hết kết thúc ván vì bên bị chiếu không thể hóa giải.',1),(8,7,'Bắt bí là trường hợp nào?','[\"Không còn nước hợp lệ nhưng không bị chiếu\",\"Bị chiếu hết\",\"Ăn được quân Xe\"]',0,'Bắt bí là hòa cờ: không còn nước đi nhưng Tướng không bị chiếu.',1),(9,9,'Khi nào nên đổi quân?','[\"Luôn luôn đổi quân\",\"Khi đổi quân có lợi về vị trí hoặc vật chất\",\"Không bao giờ đổi quân\"]',1,'Đổi quân cần phục vụ kế hoạch và đem lại lợi thế.',1),(11,10,'Tướng được đi ở đâu?','[\"Ngoài bàn cờ\",\"Trong cung 3x3\",\"Qua sông\"]',1,'Tướng chỉ đi ngang hoặc dọc một ô trong cung.',1),(12,11,'Sĩ đi như thế nào?','[\"Chéo một ô trong cung\",\"Ngang không giới hạn\",\"Chéo hai ô qua sông\"]',0,'Sĩ đi chéo một ô và không ra khỏi cung.',1),(13,12,'Tượng có được qua sông không?','[\"Có\",\"Không\",\"Chỉ khi chiếu tướng\"]',1,'Tượng chỉ hoạt động ở phần sân của mình.',1),(14,13,'Tốt sau khi qua sông được đi thêm hướng nào?','[\"Đi lùi\",\"Đi ngang\",\"Đi chéo hai ô\"]',1,'Sau khi qua sông, Tốt được đi ngang nhưng không được đi lùi.',1),(15,14,'Khi phối hợp Xe và Pháo cần chú ý gì?','[\"Mở đường và tạo ngòi cho Pháo\",\"Đặt hai quân cùng một ô\",\"Cho Xe đi chéo\"]',0,'Xe mở đường và quân làm ngòi giúp Pháo ăn đúng luật.',1),(16,15,'Mục tiêu của bài phối hợp ba quân là gì?','[\"Cho các quân hỗ trợ lẫn nhau\",\"Chỉ di chuyển Tướng\",\"Không được ăn quân\"]',0,'Xe, Pháo và Mã cần phối hợp thay vì hoạt động rời rạc.',1),(17,16,'Bàn cờ Tướng có bao nhiêu đường dọc?','[\"8\",\"9\",\"10\"]',1,'Bàn cờ có 9 đường dọc.',1),(18,16,'Quân nào đi chữ L?','[\"Mã\",\"Tượng\",\"Sĩ\"]',0,'Mã đi theo hình chữ L.',2),(19,16,'Tướng Đỏ bắt đầu ở đâu?','[\"Hàng 1 cột 4\",\"Hàng 10 cột 5\",\"Hàng 10 cột 4\"]',2,'Tướng Đỏ ở hàng cuối, cột giữa.',3),(20,16,'Sĩ di chuyển như thế nào?','[\"Chéo 1 ô trong cung\",\"Ngang 2 ô\",\"Dọc không giới hạn\"]',0,'Sĩ đi chéo một ô trong cung.',4),(21,16,'Tượng có được qua sông không?','[\"Có\",\"Không\",\"Chỉ khi ăn quân\"]',1,'Tượng không được qua sông.',5),(22,16,'Tốt sau khi qua sông được đi ngang không?','[\"Có\",\"Không\",\"Chỉ đi chéo\"]',0,'Tốt được đi ngang sau khi qua sông.',6),(23,16,'Quân nào đi ngang dọc không giới hạn?','[\"Xe\",\"Mã\",\"Tốt\"]',0,'Xe đi ngang hoặc dọc trên đường trống.',7),(24,17,'Xe có được đi xuyên qua quân khác không?','[\"Có\",\"Không\",\"Chỉ khi chiếu\"]',1,'Xe bị chặn bởi quân trên đường đi.',1),(25,17,'Pháo ăn quân cần bao nhiêu ngòi?','[\"Không cần\",\"Đúng một\",\"Hai hoặc hơn\"]',1,'Pháo phải có đúng một quân làm ngòi.',2),(26,17,'Mã bị chặn bởi bộ phận nào?','[\"Chân Mã\",\"Mắt Tượng\",\"Cung\"]',0,'Quân đứng ở chân Mã chặn hướng đi đó.',3),(27,17,'Tượng bị chặn bởi gì?','[\"Mắt Tượng\",\"Chân Mã\",\"Ngòi\"]',0,'Quân ở điểm giữa đường chéo chặn mắt Tượng.',4),(28,17,'Quân cùng màu ở ô đích xử lý thế nào?','[\"Có thể ăn\",\"Không được đi vào\",\"Được nhảy qua\"]',1,'Không thể đi vào ô đang có quân cùng phe.',5),(29,17,'Tốt có được đi lùi không?','[\"Có\",\"Không\",\"Chỉ sau khi qua sông\"]',1,'Tốt không bao giờ được đi lùi.',6),(30,17,'Sĩ có được ra khỏi cung không?','[\"Có\",\"Không\",\"Chỉ khi ăn quân\"]',1,'Sĩ chỉ hoạt động trong cung.',7),(31,17,'Quân nào có thể ăn theo đường thẳng nhưng cần ngòi?','[\"Pháo\",\"Mã\",\"Tượng\"]',0,'Pháo cần đúng một ngòi khi ăn.',8),(32,18,'Phối hợp Xe và Pháo cần tạo điều kiện gì?','[\"Đường đi và ngòi Pháo\",\"Hai quân cùng ô\",\"Không có quân chắn nào\"]',0,'Xe mở đường và quân làm ngòi hỗ trợ Pháo.',1),(33,18,'Mã hỗ trợ tốt nhất khi nào?','[\"Khi không bị cản chân\",\"Khi ở ngoài bàn\",\"Khi bị chặn\"]',0,'Mã cần ô chân thông thoáng.',2),(34,18,'Hai Tướng cùng cột cần điều kiện gì?','[\"Có quân chắn giữa\",\"Không có quân chắn\",\"Được nhìn nhau\"]',0,'Hai Tướng không được đối mặt trực tiếp.',3),(35,18,'Mục tiêu của phối hợp quân là gì?','[\"Tạo ưu thế và hỗ trợ nhau\",\"Di chuyển một quân mãi\",\"Bỏ qua Tướng\"]',0,'Các quân phối hợp để tạo ưu thế.',4),(36,18,'Khi ăn quân, quân bị ăn sẽ ở đâu?','[\"Vẫn ở ô cũ\",\"Bị loại khỏi bàn\",\"Chuyển sang bên kia\"]',1,'Quân bị ăn được loại khỏi trạng thái bàn cờ.',5),(37,18,'Vị trí khai cuộc của Pháo Đỏ là gì?','[\"Hàng 8 cột 2 và 8\",\"Hàng 10 cột 2 và 8\",\"Hàng 7 cột 1 và 7\"]',0,'Pháo Đỏ bắt đầu ở hàng áp chót, cột 1 và 7 theo chỉ số 0.',6),(38,18,'Quân nào không được qua sông?','[\"Tượng\",\"Xe\",\"Mã\"]',0,'Tượng chỉ hoạt động ở nửa bàn của mình.',7),(39,18,'Nước đi làm lộ mặt Tướng là gì?','[\"Hợp lệ\",\"Không hợp lệ\",\"Luôn là chiếu hết\"]',1,'Không được để hai Tướng đối mặt cùng cột.',8),(40,19,'Bàn cờ khai cuộc có bao nhiêu quân?','[\"16\",\"32\",\"36\"]',1,'Mỗi bên có 16 quân, cả bàn cờ có 32 quân.',1),(41,19,'Xe đi như thế nào?','[\"Ngang hoặc dọc, không xuyên quân\",\"Chéo hai ô\",\"Theo hình chữ L\"]',0,'Xe đi ngang hoặc dọc trên các đường trống.',2),(42,19,'Pháo đi thường như thế nào?','[\"Như Xe khi không ăn\",\"Chéo một ô\",\"Nhảy qua hai quân\"]',0,'Pháo đi như Xe khi di chuyển đến ô trống.',3),(43,19,'Pháo cần bao nhiêu ngòi để ăn quân?','[\"Không có\",\"Đúng một\",\"Ít nhất hai\"]',1,'Pháo phải nhảy qua đúng một quân làm ngòi.',4),(44,19,'Mã di chuyển theo hình nào?','[\"Chữ L\",\"Đường thẳng\",\"Đường chéo một ô\"]',0,'Mã đi hai ô theo một hướng rồi một ô vuông góc.',5),(45,19,'Điều gì làm Mã không đi được một hướng?','[\"Bị cản chân Mã\",\"Có sông trên bàn\",\"Đứng trong cung\"]',0,'Quân ở ô chân Mã sẽ chặn hướng đi đó.',6),(46,19,'Tượng đi bao nhiêu ô mỗi nước?','[\"Một ô ngang\",\"Hai ô chéo\",\"Ba ô dọc\"]',1,'Tượng đi chéo đúng hai ô và không được qua sông.',7),(47,19,'Điểm giữa đường chéo của Tượng được gọi là gì?','[\"Mắt Tượng\",\"Ngòi Pháo\",\"Cung tướng\"]',0,'Nếu mắt Tượng bị chặn thì hướng đó không hợp lệ.',8),(48,19,'Sĩ được đi ở đâu?','[\"Trong cung, chéo một ô\",\"Qua sông, ngang hai ô\",\"Toàn bàn, dọc không giới hạn\"]',0,'Sĩ chỉ đi chéo một ô trong cung tướng.',9),(49,19,'Tướng được đi như thế nào?','[\"Ngang hoặc dọc một ô trong cung\",\"Chéo hai ô toàn bàn\",\"Theo hình chữ L\"]',0,'Tướng chỉ đi ngang hoặc dọc một ô trong cung 3x3.',10),(50,19,'Tốt trước khi qua sông được đi thế nào?','[\"Đi thẳng một ô\",\"Đi lùi một ô\",\"Đi chéo hai ô\"]',0,'Tốt chỉ đi thẳng về phía trước trước khi qua sông.',11),(51,19,'Tốt sau khi qua sông được thêm nước đi nào?','[\"Đi ngang một ô\",\"Đi lùi một ô\",\"Nhảy qua quân\"]',0,'Sau khi qua sông, Tốt được đi ngang nhưng không được đi lùi.',12),(52,19,'Quân Đỏ có thể đi vào ô đang có quân Đỏ không?','[\"Có\",\"Không\",\"Chỉ khi chiếu tướng\"]',1,'Quân cùng màu chiếm ô đích sẽ chặn nước đi.',13),(53,19,'Khi quân Đỏ ăn quân Đen, quân Đen sẽ thế nào?','[\"Bị loại khỏi bàn\",\"Đổi thành quân Đỏ\",\"Đứng chồng lên quân Đỏ\"]',0,'Quân bị ăn được loại khỏi trạng thái bàn cờ.',14),(54,19,'Hai Tướng cùng cột phải có gì ở giữa?','[\"Ít nhất một quân chắn\",\"Không có quân nào\",\"Một ô trống duy nhất\"]',0,'Hai Tướng không được đối mặt trực tiếp; phải có quân chắn giữa.',15),(55,19,'Khi quân Đen bị ăn hết trong bài thực hành, điều gì xảy ra?','[\"Hiển thị thông báo kết thúc\",\"Tự động quay về Module 1\",\"Cho quân Đen xuất hiện lại\"]',0,'Bàn cờ thông báo hoàn thành và khóa tương tác khi không còn quân Đen.',16),(56,16,'Quân nào bảo vệ Tướng trong cung bằng nước đi chéo?','[\"Sĩ\",\"Xe\",\"Pháo\"]',0,'Sĩ đi chéo một ô trong cung tướng.',8),(57,16,'Quân nào chỉ đi chéo hai ô và không qua sông?','[\"Tượng\",\"Mã\",\"Tốt\"]',0,'Tượng đi chéo hai ô và chỉ hoạt động ở phần sân của mình.',9),(58,16,'Quân nào đi thẳng trước khi qua sông?','[\"Tốt\",\"Tướng\",\"Sĩ\"]',0,'Tốt đi thẳng một ô trước khi qua sông.',10),(59,16,'Ký hiệu nào là Tướng Đỏ?','[\"帥\",\"將\",\"仕\"]',0,'帥 là ký hiệu Tướng Đỏ; 將 là ký hiệu Tướng Đen.',11),(60,17,'Quân nào không được nhảy qua quân chắn khi đi thẳng?','[\"Xe\",\"Mã\",\"Pháo khi ăn\"]',0,'Xe không được đi xuyên qua bất kỳ quân nào.',9),(61,17,'Mắt Tượng bị chặn thì điều gì xảy ra?','[\"Nước đi chéo đó không hợp lệ\",\"Tượng được nhảy qua\",\"Tượng đổi thành Mã\"]',0,'Quân ở điểm giữa đường chéo chặn hướng đi của Tượng.',10),(62,17,'Tốt sau khi qua sông được đi ngang mấy ô mỗi nước?','[\"Một ô\",\"Hai ô\",\"Không giới hạn\"]',0,'Tốt chỉ được đi ngang một ô mỗi nước.',11),(63,17,'Quân cùng màu ở ô đích có được ăn không?','[\"Không\",\"Có\",\"Chỉ khi là Tướng\"]',0,'Quân cùng màu không thể ăn nhau và ô đó không phải ô đích hợp lệ.',12),(64,18,'Khi phối hợp Xe và Pháo, quân nào có thể tạo ngòi cho Pháo?','[\"Một quân đứng giữa Pháo và mục tiêu\",\"Quân ở ngoài bàn\",\"Không cần quân nào\"]',0,'Pháo cần đúng một quân làm ngòi giữa nó và quân bị ăn.',9),(65,18,'Nước đi của quân Đỏ phải bảo vệ điều gì?','[\"Tướng Đỏ không bị lộ mặt hoặc tự chiếu\",\"Chỉ quân Xe\",\"Ô ngoài bàn cờ\"]',0,'Không được thực hiện nước đi làm Tướng Đỏ bị lộ mặt hoặc rơi vào thế nguy hiểm.',10),(66,18,'Quân nào có thể hỗ trợ kiểm soát nhiều đường thẳng?','[\"Xe\",\"Sĩ\",\"Tượng\"]',0,'Xe kiểm soát các đường ngang và dọc khi không bị cản.',11),(67,18,'Khi một quân bị ăn, vị trí của quân đó được xử lý thế nào?','[\"Xóa khỏi bàn cờ\",\"Giữ lại dưới quân ăn\",\"Đổi màu\"]',0,'Quân bị ăn bị loại khỏi trạng thái bàn cờ.',12);
