INSERT INTO `openings` VALUES (1,'ECCO-01','Pháo Đầu (Trung Pháo)','Thế trận công thủ toàn diện, Pháo vào trung lộ kiểm soát lộ 5, tạo sức ép thẳng vào cung Tướng.','rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1'),(2,'ECCO-02','Bình Phong Mã','Trận hình phòng thủ kinh điển chống lại Pháo Đầu, hai Mã nhảy lên giữ chặt trung lộ và bảo vệ Tốt đầu vững chắc.','rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1'),(3,'ECCO-03','Thuận Pháo','Hai bên cùng đưa Pháo vào cùng một lộ trung tâm, thế cờ đối công kịch liệt, ăn miếng trả miếng.','rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1'),(4,'ECCO-04','Tiên Nhân Chỉ Lộ','Bên Đỏ khai cuộc bằng nước Tốt 7 tiến 1 hoặc Tốt 3 tiến 1 để thăm dò ý đồ chiến thuật của đối phương.','rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1'),(5,'ECCO-05','Trận Thượng Tiên (Khởi Mã Cuộc)','Khai cuộc bằng nước phát triển Mã sớm, cấu trúc phòng thủ kiên cố, linh hoạt chuyển biến.','rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1');
/*!40000 ALTER TABLE `openings` ENABLE KEYS */;
