DROP TABLE IF EXISTS `userelohistories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `userelohistories` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `UserId` int NOT NULL,
  `GameId` int DEFAULT NULL,
  `OldElo` int NOT NULL,
  `NewElo` int NOT NULL,
  `EloChange` int NOT NULL,
  `Reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `RecordedAt` datetime(6) NOT NULL,
  PRIMARY KEY (`Id`),
  KEY `IX_UserEloHistories_GameId` (`GameId`),
  KEY `IX_UserEloHistories_UserId` (`UserId`),
